import{_ as e}from"./chunks/hub.pc.en.Cb61JjFk.js";import{_ as o,o as n,c as a,a5 as r}from"./chunks/framework.D47SInms.js";const g=JSON.parse('{"title":"2. Controller & Wi-Fi Connection","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"guides/common/controller-wifi-connect.md","filePath":"guides/common/controller-wifi-connect.md","lastUpdated":1791600043000}'),i={name:"guides/common/controller-wifi-connect.md"};function s(c,t,h,l,p,d){return n(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_2-controller-wi-fi-connection" tabindex="-1">2. Controller &amp; Wi-Fi Connection <a class="header-anchor" href="#_2-controller-wi-fi-connection" aria-label="Permalink to &quot;2. Controller &amp; Wi-Fi Connection&quot;">​</a></h1><p><strong>Goal:</strong> Connect the controller to the robot Wi-Fi, then connect the RBQ app to the robot and complete the automatic start so the robot is ready to operate.</p><p><strong>Prerequisites:</strong> <a href="/RBQ/nightly/guides/common/initial-pose.html">Initial Pose &amp; Power On</a> must be completed first — the robot must be on and initialized.</p><h2 id="step-1-wi-fi-connection" tabindex="-1">Step 1: Wi-Fi connection <a class="header-anchor" href="#step-1-wi-fi-connection" aria-label="Permalink to &quot;Step 1: Wi-Fi connection&quot;">​</a></h2><p>The robot provides a Wi-Fi access point named <code>RBQ_{XX}</code> (XX differs by unit). Connect the controller (Steam Deck, tablet or PC) to that network.</p><p>The app opens on the <strong>hub</strong>, and the status line after the robot name says whether the device is on the right network.</p><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+e+'" alt="The hub — robot name and status line" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ The hub ]</figcaption></figure><ol><li><strong>Read the status line</strong> - <code>Connect to the robot&#39;s WiFi</code> means no robot is saved yet; <code>Not on the robot&#39;s WiFi</code> means the device is on another network, and the app names the robot&#39;s WiFi when it knows it.</li><li><strong>Select the robot network</strong> - On Linux desktop and Steam Deck, <code>Switch WiFi</code> next to the line joins that network or opens the in-app list so you can pick <code>RBQ_{XX}</code>. Android offers <code>WiFi settings</code>; on iOS and the web build, join from the device&#39;s own Wi-Fi settings. (If it does not appear, check robot power and Wi-Fi operation.)</li><li><strong>Confirm</strong> - You are ready once the dot in front of the robot name turns green.</li></ol><p>The full procedure is in <a href="/RBQ/nightly/manual/operation/controller-wifi-connect.html#wifi">Controller and Wi-Fi</a>.</p><h2 id="connect" tabindex="-1">Step 2: Connect the app to the robot <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;Step 2: Connect the app to the robot {#connect}&quot;">​</a></h2><p>Open the RBQ app and connect it to the robot. The procedure — entering the robot address, connecting and checking the link status — is described in <strong><a href="/RBQ/nightly/manual/gui/connection.html">Connection</a></strong>.</p><h2 id="auto-start" tabindex="-1">Step 3: Auto start <a class="header-anchor" href="#auto-start" aria-label="Permalink to &quot;Step 3: Auto start {#auto-start}&quot;">​</a></h2><p>Bring up the robot software and state with the automatic start sequence from the control screen. See <strong><a href="/RBQ/nightly/manual/gui/control-home.html">Control home</a></strong> for the sequence and how to confirm that every item has completed. If an item fails, keep people away from the robot, review the <a href="/RBQ/nightly/manual/safety/emergency-stop-procedures.html">emergency stop procedures</a>, and follow the <a href="/RBQ/nightly/manual/safety/general-safety-warning-precautions.html">general safety guidelines</a>. If the problem persists, contact Rainbow Robotics via <a href="/RBQ/nightly/manual/support/">error reporting</a>.</p><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>The robot is connected and ready to drive. The app&#39;s screens and buttons are covered in <strong><a href="/RBQ/nightly/manual/gui/introduction.html">the RBQ app</a></strong>, <strong><a href="/RBQ/nightly/manual/gui/control-home.html">Control home</a></strong> and <strong><a href="/RBQ/nightly/manual/gui/motion-commands.html">Motion commands</a></strong>.</p><p>What to do once you are finished operating:</p><p><strong><a href="/RBQ/nightly/guides/common/charging.html">→ 3. Charging</a></strong></p>',17)])])}const f=o(i,[["render",s]]);export{g as __pageData,f as default};
